    "versets_count": 200,
    "theme": "La sourate du dialogue avec les gens du Livre et de l'épreuve d'Uḥud : la naissance de Marie et de Jésus, le défi de la mubāhala, le cordon d'Allah auquel s'attacher tous ensemble, la défaite retournée en leçon, et les doués d'intelligence qui méditent la création",
    "note_pedagogique": "Révélée pour l'essentiel autour de la venue de la délégation chrétienne de Najrān et de la bataille d'Uḥud. Elle porte le nom de la famille de ʿImrān — père de Marie — et déroule le plus long récit coranique de la naissance de Marie et de l'annonce faite à elle. Son cœur : « attachez-vous tous ensemble au cordon d'Allah et ne vous divisez pas » (v.103). Sa fin : les ūlū l-albāb, ceux qui se rappellent Allah debout, assis, couchés, et méditent la création des cieux et de la terre (v.190-191).",
