      "numero": 10,
      "ar": "إِنَّ الَّذِينَ كَفَرُواْ لَن تُغْنِيَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَا أَوْلَٰدُهُم مِّنَ اللَّهِ شَيْـءًا وَأُوْلَـٰئِكَ هُمْ وَقُودُ النَّارِ",
      "translit": "Inna lladhīna kafarū lan tughniya ʿanhum amwāluhum walā awlāduhum mina llāhi shayʾan waʾūlāʾika hum waqūdu n-nār",
