      "ar": "أَمْ حَسِبْتُمْ أَن تَدْخُلُواْ الْجَنَّةَ وَلَمَّا يَعْلَمِ اللَّهُ الَّذِينَ جَٰهَدُواْ مِنكُمْ وَيَعْلَمَ الصَّـٰبِرِينَ",
      "translit": "Am ḥasibtum an tadkhulū l-jannata walammā yaʿlami llāhu lladhīna jāhadū minkum wayaʿlama ṣ-ṣābirīn",
