      "ar": "إِنَّ فِي خَلْقِ السَّمَٰوَٰتِ وَالْأَرْضِ وَاخْتِلَٰفِ الَّيْلِ وَالنَّهَارِ لَأيَٰتٍ لِّأُوْلِي الْأَلْبَٰبِ",
      "translit": "Inna fī khalqi s-samāwāti wal-ʾarḍi wakhtilāfi llayli wan-nahāri laʾyātin liʾūlī l-ʾalbāb",
