      "ar": "الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَٰوَٰتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَكَ فَقِنَا عَذَابَ النَّارِ",
      "translit": "Alladhīna yadhkurūna llāha qiyāman waquʿūdan waʿalā junūbihim wayatafakkarūna fī khalqi s-samāwāti wal-ʾarḍi rabbanā mā khalaqta hādhā bāṭilan subḥānaka faqinā ʿadhāba n-nār",
